<template>
  <section
    class="fragments-page"
    :class="{ 'is-category-transitioning': categoryTransitionActive }"
  >
    <header class="fragments-hero" data-scroll-reveal>
      <h1>{{ copy.heading }}</h1>
      <p class="fragments-intro">{{ copy.intro }}</p>
      <div class="fragments-hero-image" data-scroll-reveal>
        <img src="/assets/img/fragments_light.png" alt="Fragments" class="fragments-hero-image-light" loading="lazy" decoding="async">
        <img src="/assets/img/fragments_dark.png" alt="" class="fragments-hero-image-dark" loading="lazy" decoding="async" aria-hidden="true">
      </div>
      <div class="fragments-controls" aria-label="Fragment tools">
        <div
          class="category-segmented"
          :class="{ life: activeCategory === 'life' }"
          role="group"
          aria-label="Fragment category"
        >
          <span class="category-thumb" aria-hidden="true"></span>
          <button
            type="button"
            class="category-option category-ideas"
            :aria-pressed="(activeCategory === 'ideas').toString()"
            @click="setCategory('ideas')"
          >
            <span>Ideas</span>
            <span class="category-count">{{ ideaCount }}</span>
          </button>
          <button
            type="button"
            class="category-option category-life"
            :aria-pressed="(activeCategory === 'life').toString()"
            @click="setCategory('life')"
          >
            <span>Life</span>
            <span class="category-count">{{ lifeCount }}</span>
          </button>
        </div>
        <label class="fragment-search" aria-label="Search fragments">
          <input
            v-model="searchQuery"
            class="fragment-search-input"
            type="search"
            autocomplete="off"
            spellcheck="false"
            placeholder="Search fragments"
            @keydown.esc.prevent="clearSearch"
          >
          <i class="fa fa-search fragment-search-icon" aria-hidden="true"></i>
        </label>
      </div>
    </header>

    <div class="fragment-list" data-scroll-group data-scroll-step="120">
      <article
        v-for="(fragment, fragmentIndex) in filteredFragments"
        :id="fragment.id"
        :key="fragment.id"
        class="fragment-card"
        :class="{ 'is-lifted': isOpen(fragment.id), 'is-restoring': restoringFragmentId === fragment.id }"
        :style="{
          viewTransitionName: categoryTransitionActive
            ? `fragment-category-card-${fragmentIndex}`
            : 'none'
        }"
        data-scroll-reveal
      >
        <div
          class="fragment-summary"
          data-press-intent="custom"
          :class="{ 'is-pressed': pressedFragmentId === fragment.id }"
          role="button"
          tabindex="0"
          :aria-expanded="isOpen(fragment.id).toString()"
          @pointerdown="startFragmentPress(fragment.id, $event)"
          @pointerup="finishFragmentPress(fragment.id)"
          @pointercancel="cancelFragmentPress(fragment.id)"
          @click="toggleFragment(fragment.id)"
          @keydown.enter.prevent="toggleFragment(fragment.id)"
          @keydown.space.prevent="toggleFragment(fragment.id)"
        >
          <h2 v-html="highlightText(fragment.title)"></h2>
          <p class="fragment-teaser" v-html="highlightText(fragment.teaser)"></p>
          <span class="read-cue">
            {{ copy.read }}
            <i class="fas fa-plus" aria-hidden="true"></i>
          </span>
        </div>

      </article>
    </div>
    <p v-if="searchActive && !filteredFragments.length" class="fragments-empty">
      No matching fragments.
    </p>

    <Teleport to="body">
      <div
        v-if="activeFragment"
        ref="fragmentOverlay"
        class="fragment-overlay"
        role="presentation"
        @click.self="closeFragment"
      >
        <article
          ref="floatingPaper"
          class="fragment-floating-paper"
          role="dialog"
          aria-modal="true"
          :aria-labelledby="`floating-${activeFragment.id}`"
        >
          <button type="button" class="fragment-floating-close" aria-label="Close fragment" @click="closeFragment">×</button>
          <p class="fragment-floating-kind">{{ activeFragment.category === 'life' ? 'Life fragment' : 'Idea fragment' }}</p>
          <h2 :id="`floating-${activeFragment.id}`" v-html="highlightText(activeFragment.title)"></h2>
          <p class="fragment-floating-teaser" v-html="highlightText(activeFragment.teaser)"></p>
          <div class="fragment-floating-body">
            <p
              v-for="(paragraph, index) in activeFragment.body"
              :key="`${activeFragment.id}-floating-${index}`"
              v-html="highlightText(paragraph)"
            ></p>
            <SourceViewLinks :source-id="`fragments:${activeFragment.id}`" />
          </div>
        </article>
      </div>
    </Teleport>
  </section>
</template>

<script>
import { acquireInteractiveCursorLock } from '../utils/interactiveCursorLock';
import { fragments } from '../data/fragments';
import { settleScrollToId } from '../utils/anchorLanding';
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import SourceViewLinks from './ui/SourceViewLinks.vue';

function shuffleFragments(items) {
  const shuffled = [...items];

  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  return shuffled;
}

export default {
  name: 'FragmentsTab',
  components: { SourceViewLinks },
  mixins: [scrollRevealMixin],
  data() {
    return {
      activeCategory: 'ideas',
      openIds: [],
      pressedFragmentId: '',
      restoringFragmentId: '',
      categoryTransitionActive: false,
      searchQuery: '',
      shuffledFragments: shuffleFragments(fragments)
    };
  },
  computed: {
    ideaFragments() {
      return this.shuffledFragments.filter((fragment) => fragment.category === 'ideas');
    },
    lifeFragments() {
      return this.shuffledFragments.filter((fragment) => fragment.category === 'life');
    },
    ideaCount() {
      return this.searchActive
        ? this.ideaFragments.filter((fragment) => this.fragmentMatches(fragment)).length
        : this.ideaFragments.length;
    },
    lifeCount() {
      return this.searchActive
        ? this.lifeFragments.filter((fragment) => this.fragmentMatches(fragment)).length
        : this.lifeFragments.length;
    },
    copy() {
      return {
        heading: 'Fragments',
        intro: 'Fragments is where I keep thoughts and moments that I feel deserve a place in my memory. Many grow out of ideas I explore in my free time and gradually take shape as I think them through. Others come from places, conversations, memories, or small things I notice in everyday life. I write them down before they fade.',
        read: 'Read',
        close: 'Close'
      };
    },
    filteredFragments() {
      const categoryFragments = this.activeCategory === 'life' ? this.lifeFragments : this.ideaFragments;
      if (this.searchActive) {
        return categoryFragments.filter((fragment) => this.fragmentMatches(fragment));
      }
      return categoryFragments;
    },
    activeFragment() {
      return this.openIds.length ? this.fragmentById(this.openIds[0]) : null;
    },
    searchActive() {
      return this.searchTerms.length > 0;
    },
    searchTerms() {
      return this.searchQuery
        .toLowerCase()
        .split(/[\s,.;:!?()[\]{}"']+/)
        .map((term) => term.trim())
        .filter((term) => term.length >= 2);
    }
  },
  watch: {
    '$route.hash'() {
      this.activateHashFragment();
    },
    searchQuery() {
      if (this.searchActive) {
        this.openIds = [];
      }
      this.refreshScrollReveal();
    },
    activeCategory() {
      this.refreshScrollReveal();
    }
  },
  created() {
    // The category must be switched and the card opened before it can be
    // scrolled into view; mounted() then owns the landing for this tab.
    this.activateHashFragment(false);
  },
  mounted() {
    this.activateHashFragment();
    window.addEventListener('hashchange', this.activateHashFragment);
    window.addEventListener('keydown', this.handleFragmentKeydown);
    this._fragmentAnims = new Set();
  },
  unmounted() {
    window.removeEventListener('hashchange', this.activateHashFragment);
    window.removeEventListener('keydown', this.handleFragmentKeydown);
    window.clearTimeout(this._fragmentPressTimer);
    window.clearTimeout(this._fragmentPressIntentTimer);
    window.clearTimeout(this._fragmentOpenTimer);
    if (this._fragmentAnims) {
      this._fragmentAnims.forEach((animation) => animation.cancel());
      this._fragmentAnims.clear();
    }
    if (this._categoryTransition && this._categoryTransition.skipTransition) {
      this._categoryTransition.skipTransition();
    }
    document.documentElement.style.removeProperty('--fragment-category-direction');
  },
  methods: {
    startFragmentPress(id, event) {
      if (event.pointerType === 'mouse' && event.button !== 0) return;
      window.clearTimeout(this._fragmentPressTimer);
      window.clearTimeout(this._fragmentPressIntentTimer);
      if (event.currentTarget && event.currentTarget.setPointerCapture) {
        event.currentTarget.setPointerCapture(event.pointerId);
      }
      this._fragmentPressStartedAt = window.performance ? window.performance.now() : Date.now();
      this._fragmentPressCandidateId = id;
      this._fragmentPressIntentTimer = window.setTimeout(() => {
        if (this._fragmentPressCandidateId !== id) return;
        this._fragmentPressVisibleAt = window.performance ? window.performance.now() : Date.now();
        this.pressedFragmentId = id;
      }, 120);
    },
    finishFragmentPress(id) {
      window.clearTimeout(this._fragmentPressIntentTimer);
      this._fragmentPressCandidateId = '';
      if (this.pressedFragmentId !== id) return;
      const now = window.performance ? window.performance.now() : Date.now();
      const elapsed = now - (this._fragmentPressVisibleAt || now);
      const feedbackFloor = Math.max(0, 120 - elapsed);
      const remaining = Math.max(feedbackFloor, 150 - elapsed);

      this._fragmentReleasedPressId = id;
      this._fragmentActivationDelay = remaining + (this.prefersReducedMotion() ? 0 : 180);

      window.clearTimeout(this._fragmentPressTimer);
      if (remaining === 0) {
        this.pressedFragmentId = '';
        return;
      }

      this._fragmentPressTimer = window.setTimeout(() => {
        if (this.pressedFragmentId === id) this.pressedFragmentId = '';
      }, remaining);
    },
    cancelFragmentPress(id) {
      window.clearTimeout(this._fragmentPressIntentTimer);
      this._fragmentPressCandidateId = '';
      this._fragmentReleasedPressId = '';
      this._fragmentActivationDelay = 0;
      if (this.pressedFragmentId !== id) return;
      window.clearTimeout(this._fragmentPressTimer);
      this.pressedFragmentId = '';
    },
    currentHashId() {
      const routeHash = this.$route && this.$route.hash ? this.$route.hash : '';
      const browserHash = typeof window !== 'undefined' ? window.location.hash : '';
      let raw = routeHash;

      // In hash-router URLs the browser hash can look like "#/fragments#entry-id".
      // Vue usually exposes the second hash as this.$route.hash, but parse it here too
      // so direct browser/hashchange paths are safe.
      if (!raw && browserHash.startsWith('#/')) {
        const secondHash = browserHash.indexOf('#', 1);
        if (secondHash >= 0) raw = browserHash.slice(secondHash);
      }
      if (!raw) raw = browserHash;
      if (!raw) return '';

      try {
        return decodeURIComponent(raw.replace(/^#/, ''));
      } catch (err) {
        return raw.replace(/^#/, '');
      }
    },
    fragmentById(id) {
      return fragments.find((fragment) => fragment.id === id);
    },
    escapeHtml(text) {
      return String(text == null ? '' : text)
        .split('&').join('&amp;')
        .split('<').join('&lt;')
        .split('>').join('&gt;')
        .split(String.fromCharCode(34)).join('&quot;')
        .split("'").join('&#39;');
    },
    escapeRegExp(text) {
      return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    },
    fragmentSearchText(fragment) {
      return [
        fragment.title,
        fragment.teaser,
        ...(Array.isArray(fragment.body) ? fragment.body : [])
      ].join(' ').toLowerCase();
    },
    fragmentMatches(fragment) {
      const terms = this.searchTerms;
      if (!terms.length) return false;
      const text = this.fragmentSearchText(fragment);
      return terms.every((term) => text.includes(term));
    },
    highlightText(text) {
      const escaped = this.escapeHtml(text);
      const terms = [...new Set(this.searchTerms)]
        .sort((a, b) => b.length - a.length)
        .map((term) => this.escapeRegExp(term));
      if (!terms.length) return escaped;

      const re = new RegExp(`(${terms.join('|')})`, 'gi');
      return escaped.replace(re, '<mark>$1</mark>');
    },
    clearSearch() {
      this.searchQuery = '';
    },
    activateHashFragment(shouldScroll = true) {
      const id = this.currentHashId();
      if (!id) return;

      const fragment = this.fragmentById(id);
      if (!fragment) return;

      if (fragment.category && this.activeCategory !== fragment.category) {
        this.activeCategory = fragment.category;
      }

      if (!this.openIds.includes(id)) {
        this.openIds = [id];
      }

      if (!shouldScroll) return;

      this.$nextTick(() => {
        this.scrollToHashFragment(id, 0);
      });
    },
    scrollToHashFragment(id, attempt = 0) {
      const el = document.getElementById(id);
      if (!el) {
        if (attempt < 20) {
          window.setTimeout(() => this.scrollToHashFragment(id, attempt + 1), 80);
        }
        return;
      }

      window.setTimeout(() => {
        settleScrollToId(id);
        window.dispatchEvent(new Event('scroll'));
      }, 120);
    },
    async setCategory(category) {
      if (this.activeCategory === category) return;
      if (this._categoryTransition && this._categoryTransition.skipTransition) {
        this._categoryTransition.skipTransition();
      }

      const applyCategory = async () => {
        this.activeCategory = category;
        this.openIds = [];
        await this.$nextTick();
      };
      const reduceMotion = this.prefersReducedMotion();
      if (!document.startViewTransition || reduceMotion) {
        await applyCategory();
        return;
      }

      const transitionToken = (this._categoryTransitionToken || 0) + 1;
      this._categoryTransitionToken = transitionToken;
      const releaseCursorLock = acquireInteractiveCursorLock();
      this.categoryTransitionActive = true;
      document.documentElement.style.setProperty(
        '--fragment-category-direction',
        category === 'life' ? '1' : '-1'
      );
      await this.$nextTick();

      let transition;
      try {
        transition = document.startViewTransition(applyCategory);
      } catch (error) {
        releaseCursorLock();
        this.categoryTransitionActive = false;
        document.documentElement.style.removeProperty('--fragment-category-direction');
        await applyCategory();
        return;
      }
      this._categoryTransition = transition;
      transition.finished.catch(() => {}).finally(() => {
        releaseCursorLock();
        if (this._categoryTransitionToken !== transitionToken) return;
        this._categoryTransition = null;
        this.categoryTransitionActive = false;
        document.documentElement.style.removeProperty('--fragment-category-direction');
      });
    },
    isOpen(id) {
      return this.openIds.includes(id);
    },
    toggleFragment(id) {
      if (this.isOpen(id)) {
        this.closeFragment();
        return;
      }

      window.clearTimeout(this._fragmentOpenTimer);
      const isPointerPress = this.pressedFragmentId === id || this._fragmentReleasedPressId === id;
      const activationDelay = isPointerPress ? (this._fragmentActivationDelay || 180) : 0;
      this._fragmentReleasedPressId = '';
      this._fragmentActivationDelay = 0;

      this._fragmentOpenTimer = window.setTimeout(() => {
        this.pressedFragmentId = '';
        window.requestAnimationFrame(() => {
          const source = document.getElementById(id);
          this._fragmentSourceRect = source ? source.getBoundingClientRect() : null;
          this._fragmentReturnTarget = source && source.querySelector('.fragment-summary');
          this.openIds = [id];
          this.$nextTick(() => this.animateFragmentOpen());
        });
      }, activationDelay);
    },
    handleFragmentKeydown(event) {
      if (event.key === 'Escape' && this.activeFragment) this.closeFragment();
    },
    prefersReducedMotion() {
      return window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    },
    fragmentOriginTransform(sourceRect, paperRect) {
      if (!sourceRect || !paperRect) return 'translate3d(0, 14px, 0) scale(0.97)';
      const dx = sourceRect.left + sourceRect.width / 2 - (paperRect.left + paperRect.width / 2);
      const dy = sourceRect.top + sourceRect.height / 2 - (paperRect.top + paperRect.height / 2);
      const scale = Math.max(0.72, Math.min(0.96, sourceRect.width / paperRect.width));
      return `translate3d(${dx}px, ${dy}px, 0) scale(${scale})`;
    },
    trackFragmentAnimation(animation) {
      this._fragmentAnims.add(animation);
      animation.finished.catch(() => {}).finally(() => this._fragmentAnims.delete(animation));
      return animation;
    },
    animateFragmentOpen() {
      const paper = this.$refs.floatingPaper;
      const overlay = this.$refs.fragmentOverlay;
      if (!paper || !overlay) return;

      const reduceMotion = this.prefersReducedMotion();
      const origin = this.fragmentOriginTransform(this._fragmentSourceRect, paper.getBoundingClientRect());
      this.trackFragmentAnimation(overlay.animate(
        [{ opacity: 0 }, { opacity: 1 }],
        { duration: reduceMotion ? 120 : 220, easing: 'ease-out', fill: 'both' }
      ));
      const paperAnimation = this.trackFragmentAnimation(paper.animate(
        reduceMotion
          ? [{ opacity: 0 }, { opacity: 1 }]
          : [
            { transform: origin, opacity: 0.18, filter: 'blur(2px)' },
            { transform: 'translate3d(0, 0, 0) scale(1)', opacity: 1, filter: 'blur(0)' }
          ],
        { duration: reduceMotion ? 140 : 340, easing: 'cubic-bezier(0.23, 1, 0.32, 1)', fill: 'both' }
      ));
      paperAnimation.finished.catch(() => {}).then(() => {
        const close = paper.querySelector('.fragment-floating-close');
        if (close) close.focus({ preventScroll: true });
      });
    },
    closeFragment() {
      const paper = this.$refs.floatingPaper;
      const overlay = this.$refs.fragmentOverlay;
      if (!paper || !overlay) {
        this.openIds = [];
        return;
      }

      this._fragmentAnims.forEach((animation) => animation.cancel());
      this._fragmentAnims.clear();
      const source = this.activeFragment ? document.getElementById(this.activeFragment.id) : null;
      const sourceRect = source ? source.getBoundingClientRect() : this._fragmentSourceRect;
      const target = this.fragmentOriginTransform(sourceRect, paper.getBoundingClientRect());
      const reduceMotion = this.prefersReducedMotion();
      if (source) this.restoringFragmentId = source.id;

      this.trackFragmentAnimation(overlay.animate(
        [{ opacity: 1 }, { opacity: 0 }],
        { duration: reduceMotion ? 100 : 190, easing: 'ease-out', fill: 'both' }
      ));
      const paperAnimation = this.trackFragmentAnimation(paper.animate(
        reduceMotion
          ? [{ opacity: 1 }, { opacity: 0 }]
          : [
            { transform: 'translate3d(0, 0, 0) scale(1)', opacity: 1, filter: 'blur(0)' },
            { transform: target, opacity: 0.08, filter: 'blur(2px)' }
          ],
        { duration: reduceMotion ? 110 : 250, easing: 'cubic-bezier(0.23, 1, 0.32, 1)', fill: 'both' }
      ));
      paperAnimation.finished.catch(() => {}).then(() => {
        this.openIds = [];
        this.$nextTick(() => {
          window.requestAnimationFrame(() => {
            window.requestAnimationFrame(() => {
              this.restoringFragmentId = '';
            });
          });
          if (this._fragmentReturnTarget && this._fragmentReturnTarget.isConnected) {
            this._fragmentReturnTarget.focus({ preventScroll: true });
          }
        });
      });
    }
  }
};
</script>

